[
  {
    "statement": "Several interventions have been documented for restoring degraded shrubland habitats.",
    "citations": []
  },
  {
    "statement": "Topsoil removal has been used as a restoration technique.",
    "citations": []
  },
  {
    "statement": "A study in the Netherlands found that heathlands restored by topsoil removal had higher butterfly abundance in areas where heather litter had also been spread compared to areas where heather litter had not been spread.",
    "citations": [
      "3946"
    ]
  },
  {
    "statement": "Temporary irrigation has been shown to increase shrub cover in degraded shrublands.",
    "citations": []
  },
  {
    "statement": "A study in the USA demonstrated that irrigation increased shrub cover.",
    "citations": [
      "1696"
    ]
  },
  {
    "statement": "Shrubland restoration has generally achieved similar biodiversity outcomes to undisturbed areas.",
    "citations": []
  },
  {
    "statement": "Studies in the USA and Mexico found that restored desert scrub or shrubland had mammal species richness similar to undisturbed areas.",
    "citations": [
      "2569"
    ]
  },
  {
    "statement": "A Mexico study found areas of restored shrubland had similar reptile and amphibian species richness compared to non-restored areas.",
    "citations": [
      "3751"
    ]
  },
  {
    "statement": "A study in Mexico found restored shrubland areas had a higher abundance of lizards compared to non-restored areas.",
    "citations": [
      "3751"
    ]
  },
  {
    "statement": "In the UK, restored moorland developed moth communities more similar to established heather moorland than degraded moorland.",
    "citations": [
      "3946"
    ]
  },
  {
    "statement": "One UK study reported that a population of silver-studded blue butterflies released into a site managed for heathland restoration increased in abundance over 11 years.",
    "citations": [
      "3946"
    ]
  },
  {
    "statement": "The butterfly population also expanded its range beyond the initial release area.",
    "citations": [
      "3946"
    ]
  },
  {
    "statement": "For bird populations, a UK study found that one or two pairs of northern lapwing bred on restored moorland where the birds had not previously bred.",
    "citations": [
      "364"
    ]
  }
]

